import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        long[] a = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) total += a[i] = next();
        long left = 0;
        for (int i = 0; i < n; i++) {
            if (left == total - left - a[i]) {
                System.out.println(i);
                return;
            }
            left += a[i];
        }
        System.out.println(-1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	a := make([]int64, n)
	var total int64
	for i := range a {
		a[i] = next()
		total += a[i]
	}
	var left int64
	for i, v := range a {
		if left == total-left-v {
			fmt.Println(i)
			return
		}
		left += v
	}
	fmt.Println(-1)
}
